private boolean setVagrant(boolean vagrant, RemnantStateChangeCallback.Cause cause) {
        boolean soul = this.isVagrant();

        if (soul != vagrant) {
            if (this.state.setVagrant(vagrant)) {
                this.fireRemnantStateChange(soul, cause);
                return true;
            }
            return false;
        }
        return true;
    }

